mapper.select:
SELECT id, device_id, coalesce(custom_name, name) as name, password, manufacturer, model, firmware, transport, stream_mode, ip, sdp_ip, local_ip, port, host_address, expires, register_time, keepalive_time, create_time, update_time, charset, subscribe_cycle_for_catalog, subscribe_cycle_for_mobile_position, mobile_position_submission_interval, subscribe_cycle_for_alarm, ssrc_check, as_message_channel, broadcast_push_after_ack, geo_coord_sys, on_line, media_server_id, (SELECT count(0) FROM wvp_device_channel dc WHERE dc.data_type = #{dataType} and dc.data_device_id= de.id) as channel_count FROM wvp_device de
AND de.on_line = #{online}
ORDER BY de.create_time DESC
